begin;

create table platform.rpg_master_catalog (
  entity_type text not null check (entity_type in ('region', 'quest', 'enemy', 'dungeon', 'item', 'level')),
  entity_id text not null,
  version text not null default 'v1',
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  created_at timestamptz not null default now(),
  primary key (entity_type, entity_id, version)
);

alter table platform.rpg_master_catalog enable row level security;
revoke all on table platform.rpg_master_catalog from anon, authenticated;
grant select on table platform.rpg_master_catalog to authenticated;
create policy rpg_master_catalog_read on platform.rpg_master_catalog
  for select to authenticated using (true);


commit;
